window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-50d09cfc73aa988c"]={"versions": [{"id": "FIG-50d09cfc73aa988c", "releases": ["R2.1.20"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Sequenzdiagramm (Nachrichtenaustauschdiagramm) im Kontext des AUTOSAR CAN Transport Layer (CanTp) gemäß ISO 15765-2. Das Diagramm illustriert den grundlegenden Protokollablauf einer segmentierten Datenübertragung (Multiple Parts Message / Segmented Data Transfer) über einen CAN-Bus zwischen zwei Kommunikationspartnern.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>Sender</strong>: Sendende CanTp-Instanz (Transmitter), agiert als Quelle der segmentierten Nachricht.\n</li><li><strong>Receiver</strong>: Empfangende CanTp-Instanz (Receiver), verarbeitet Segmente und steuert den Datenfluss.\n</li><li><strong>Protokoll-Frames (N-PDUs)</strong>:\n<ul class=\"fig-list\"><li><code>First frame</code> (FF): Erstes Segment der segmentierten Übertragung mit Gesamtlängenangabe.\n</li><li><code>Flow Control frame</code> (FC): Flusssteuerungsnachricht des Empfängers zur Definition von Blockgröße (Block Size, BS) und minimalem Sendeabstand (Separation Time, STmin).\n</li><li><code>Consecutive frame</code> (CF): Folgesegment mit Sequenzzähler zur Übertragung der Nutzlastfragmente.\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\"><li><strong>Initiierung</strong>: Der Sender übermittelt einen <code>First frame</code> an den Receiver, um die segmentierte Übertragung einzuleiten.\n</li><li><strong>Erste Flusssteuerung</strong>: Nach Erhalt des First Frame antwortet der Receiver mit einem <code>Flow Control frame</code> (FC), der die Übertragungsparameter (BS = 3) vorgibt.\n</li><li><strong>Erster Datenblock</strong>: Der Sender überträgt aufeinanderfolgend drei <code>Consecutive frame</code>-Nachrichten an den Receiver.\n</li><li><strong>Zweite Flusssteuerung</strong>: Nach Empfang des vereinbarten Blocks aus drei Consecutive Frames sendet der Receiver erneut einen <code>Flow Control frame</code>, um den nächsten Block freizugeben.\n</li><li><strong>Zweiter Datenblock</strong>: Der Sender übermittelt die verbleibenden zwei <code>Consecutive frame</code>-Nachrichten zum Abschluss der Gesamtnachricht.\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Das Diagramm dient als schematische Veranschaulichung der segmentierten PDU-Übertragung nach ISO 15765-2 innerhalb des AUTOSAR-CanTp-Moduls. Entwickler müssen bei der Implementierung beachten, dass die gezeigte Übertragung eine Blockgröße von BS = 3 abbildet, nach der jeweils ein Flow Control Frame erwartet wird. Parameter wie STmin, Timeout-Überwachungen (N_Ar, N_As, N_Br, N_Bs, N_Cr, N_Cs) und Buffer-Status (FC(CTS) vs. FC(WAIT)/FC(OVFLW)) sind gemäß den normativen CanTp-Anforderungen zu behandeln.</p>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-c665165f8e2b5cb1", "releases": ["R3.2.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Sequenzdiagramm (Nachrichtenaustauschdiagramm) im Kontext des AUTOSAR CAN Transport Layer (CanTp) gemäß ISO 15765-2. Das Diagramm illustriert den grundlegenden Protokollablauf einer segmentierten Datenübertragung (Multiple Parts Message / Segmented Data Transfer) über einen CAN-Bus zwischen zwei Kommunikationspartnern.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>Sender</strong>: Sendende CanTp-Instanz (Transmitter), agiert als Quelle der segmentierten Nachricht.\n</li><li><strong>Receiver</strong>: Empfangende CanTp-Instanz (Receiver), verarbeitet Segmente und steuert den Datenfluss.\n</li><li><strong>Protokoll-Frames (N-PDUs)</strong>:\n<ul class=\"fig-list\"><li><code>First frame</code> (FF): Erstes Segment der segmentierten Übertragung mit Gesamtlängenangabe.\n</li><li><code>Flow Control frame</code> (FC): Flusssteuerungsnachricht des Empfängers zur Definition von Blockgröße (Block Size, BS) und minimalem Sendeabstand (Separation Time, STmin).\n</li><li><code>Consecutive frame</code> (CF): Folgesegment mit Sequenzzähler zur Übertragung der Nutzlastfragmente.\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\"><li><strong>Initiierung</strong>: Der Sender übermittelt einen <code>First frame</code> an den Receiver, um die segmentierte Übertragung einzuleiten.\n</li><li><strong>Erste Flusssteuerung</strong>: Nach Erhalt des First Frame antwortet der Receiver mit einem <code>Flow Control frame</code> (FC), der die Übertragungsparameter (BS = 3) vorgibt.\n</li><li><strong>Erster Datenblock</strong>: Der Sender überträgt aufeinanderfolgend drei <code>Consecutive frame</code>-Nachrichten an den Receiver.\n</li><li><strong>Zweite Flusssteuerung</strong>: Nach Empfang des vereinbarten Blocks aus drei Consecutive Frames sendet der Receiver erneut einen <code>Flow Control frame</code>, um den nächsten Block freizugeben.\n</li><li><strong>Zweiter Datenblock</strong>: Der Sender übermittelt die verbleibenden zwei <code>Consecutive frame</code>-Nachrichten zum Abschluss der Gesamtnachricht.\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Das Diagramm dient als schematische Veranschaulichung der segmentierten PDU-Übertragung nach ISO 15765-2 innerhalb des AUTOSAR-CanTp-Moduls. Entwickler müssen bei der Implementierung beachten, dass die gezeigte Übertragung eine Blockgröße von BS = 3 abbildet, nach der jeweils ein Flow Control Frame erwartet wird. Parameter wie STmin, Timeout-Überwachungen (N_Ar, N_As, N_Br, N_Bs, N_Cr, N_Cs) und Buffer-Status (FC(CTS) vs. FC(WAIT)/FC(OVFLW)) sind gemäß den normativen CanTp-Anforderungen zu behandeln.</p>", "model": "gemini-3.8-flash (via agy)"}], "trans": [{"from": "FIG-50d09cfc73aa988c", "to": "FIG-c665165f8e2b5cb1", "fr": "R2.1.20", "tr": "R3.2.3", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
